// pokermon_391_data_test.mjs — Pokermon 3.9.1 upgrade, batch 5 (Plans/MICATRO_MODS_UPGRADES.md §3): the 3.9.1 static
// data for the jokers the port already has (micatro/mods/pokermon/data391.js, generated by
// tools/micatro/gen_pokermon_391_overlay.mjs from InertSteak/Pokermon tag 3.9.1), the cgoose -> iridescent_hacker
// rename, the version pin, and the 3.9.1 art.
//   - a sample of the taken rarities / costs / compat flags / gates / config numbers, fired through real plays where a
//     number is read in play; a sample of the SKIPPED ones (reworks: still the 3.2.1 numbers); the house rules intact
//   - the boss blind under its new key (old key resolves: aliases.js), fought
//   - version '3.9.1', contentRev 34 (pin '3.9.1+r34', the owner's Combee line; r33 the owner's Gen 3 Legendaries; r32 the owner's Starly line; r31 the owner's Regi trio; r30 the owner's types from their card art; r29 the owner's Lunatone + Solrock; r28 the owner's Barboach line; r27 the owner's Castform; r26 the owner's Spoink line; r25 the owner's Trapinch line; r24 the owner's Gulpin line; r23 the owner's Sprigatito rework; r22 the owner's Type Sleeves; r21 the owner's Whismur line; r20 the owner's Sprigatito line; r19 the owner's 25 new jokers; r18 the Hazard follow-ups (held-Hazard retriggers); r17 the leftovers batch; r16 the seals fix; batch 17 was r15 (non-Pokémon jokers, blinds, Elite, challenges, object_weights); batch 16 was r14; sub-batch 15b was r13, sub-batch 15 was r12, sub-batch 14 r11, sub-batch 13 r10, sub-batch 12 r9, sub-batch 11 r8, batch 10b r7, batch 10 r6, batch 8 r5, batch 7 r4, batch 6 r3, batch 5 r2): a 3.2.1 run / replay reads as changed
//   (batch 6 moved pokejokers_01-08 onto their 3.9.1 behaviour: pokermon_391_reworks_a_test.mjs; the samples below that
//   were batch-5 skips in that range now sit outside it)
//   - art (when it's on disk: this checkout, else the main checkout of a worktree): every Pokermon card drawn from a
//     3.9.1 sheet shows, at its new cell, the same picture its 3.2.1 cell showed (mean |diff| per channel <= 3,
//     i.e. 3.9.1's touch-ups) — except the cards 3.9.1 redrew on purpose (listed). Streams the PNGs (crops only).
//   node micatro/tests/mods/pokermon_391_data_test.mjs
import path from 'path';
import { T, start, hand, add, play, winRound, nextRound, clearHand, G, P_CENTERS, act } from './poke_helpers.mjs';
import { P_BLINDS, get_new_boss } from '../../js/engine/core.js';
import { MODS, ATLASES } from '../../js/mods/registry.js';
import { ART, crops } from './poke_art_helpers.mjs';
import * as PINS from '../../js/mods/pins.js';
import * as AL from '../../js/mods/aliases.js';
import { Session } from '../../js/engine/session.js';
import DATA from '../../mods/pokermon/data.js';
import D391 from '../../mods/pokermon/data391.js';
import * as P from '../../mods/pokermon/api.js';

const { ok, done } = T();
const C = (n) => P_CENTERS['j_poke_' + n];

// ---------------------------------------------------------------- version pin
ok(MODS.pokermon.version === '3.9.1' && MODS.pokermon.contentRev === 34, 'Pokermon is version 3.9.1, contentRev 34', [MODS.pokermon.version, MODS.pokermon.contentRev]);
ok(PINS.modPin('pokermon') === '3.9.1+r34', 'its pin is 3.9.1+r34', PINS.modPin('pokermon'));
ok(PINS.LEGACY_MOD_VERSIONS.pokermon === '3.2.1+r1', 'the legacy table still reads old recipes as 3.2.1+r1 (frozen)');
{
  const s = new Session();
  s.start({ seed: 'PK391PIN', mods: ['pokermon'] });
  ok(s.recipe.modVersions.pokermon === '3.9.1+r34', 'a new run is pinned 3.9.1+r34', s.recipe.modVersions);
  const old = { ...s.recipe, modVersions: { pokermon: '3.2.1+r1' } };
  const d = Session.pinDiff(old);
  ok(d.length === 1 && d[0].recorded === '3.2.1+r1' && d[0].current === '3.9.1+r34', 'a run recorded on 3.2.1+r1 differs (the resume prompt)', d);
  ok(PINS.replayWarning(d) === 'Recorded with Pokermon 3.2.1 (rev 1); current 3.9.1 (rev 34). Playback may differ.', 'the replay banner names both versions', PINS.replayWarning(d));
  const legacy = { ...s.recipe };
  delete legacy.modVersions; delete legacy.engineRev;
  ok(Session.pinDiff(legacy).some((x) => x.id === 'pokermon' && x.recorded === '3.2.1+r1'), 'a pre-pin recipe (legacy) differs too');
}

// ---------------------------------------------------------------- the overlay itself
ok(D391.version === '3.9.1' && D391.counts.rarity === 41 && D391.counts.cost === 7 && D391.counts.enhancement_gate === 7, '3.9.1 overlay: 41 rarities, 7 costs, 7 gates', D391.counts);
// (batch 6: the 4 taken config numbers of pokejokers_01-08 — Voltorb, Electrode, Primeape, Ursaring — now come with their whole
// 3.9.1 config, config_all; so does Mega Pidgeot's blueprint flag)
// (batch 7: Larvitar, Pupitar and Kricketot - pokejokers_09/14 - likewise; batch 8: the last two, Grubbin and Charjabug)
ok(!D391.counts.config && D391.counts.attributes === 451, '... no config number taken outside the reworked files any more (batch 8)', D391.counts);
// (batch 10: the Hazard / Seed / quantum holds left; batch 10b: Unown (its format-only change) too — nothing is skipped now)
ok(D391.skipped.length === 0 && D391.skipped.every((s) => s.length === 5 && typeof s[4] === 'string' && s[4] && s[4] !== '?'), 'every skipped change has a reason', D391.skipped.filter((s) => !s[4] || s[4] === '?'));

// ---------------------------------------------------------------- rarities (mostly to Safari)
const RAR = { raticate: 'poke_safari', fearow: 'poke_safari', sandslash: 'poke_safari', nidorina: 'poke_safari', golduck: 'poke_safari',
  primeape: 'poke_safari', kadabra: 'poke_safari', electrode: 'poke_safari', boldore: 'poke_safari', dachsbun: 'poke_safari',
  golbat: 3, lucario: 3, meowth: 1, farfetchd: 1, koffing: 1, rhyhorn: 1, numel: 1, ditto: 3, horsea: 2, charcadet: 2, rotomdex: 2 };
for (const [n, r] of Object.entries(RAR)) ok(C(n).rarity === r, `rarity: ${n} -> ${r}`, C(n).rarity);
// (and the 3.2.1 ones that 3.9.1 kept)
ok(C('bulbasaur').rarity === DATA.groups.jokers[0].ret.list[0].rarity && C('mewtwo').rarity === 4, 'unchanged rarities stay');

// ---------------------------------------------------------------- costs
const COST = { fearow: 6, sandshrew: 4, horsea: 6, houndour: 4, houndoom: 7, dachsbun: 7, rival: 5 };
for (const [n, c] of Object.entries(COST)) ok(C(n).cost === c, `cost: ${n} $${c}`, C(n).cost);

// ---------------------------------------------------------------- compat flags
ok(C('mega_pidgeot').blueprint_compat === true && C('pokedex').blueprint_compat === false && C('professor').blueprint_compat === false && C('treasure_eatery').blueprint_compat === false, 'blueprint_compat: Mega Pidgeot on; Pokédex / Professor / Treasure Eatery off');
ok(C('spidops').blueprint_compat === false && C('mega_steelix').blueprint_compat === false, 'blueprint_compat: Spidops / Mega Steelix take their 3.9.1 flag (reworked since batch 10)');
ok(C('vanillite').blueprint_compat === true, 'Vanillite (pokejokers_20, batch 8) takes its 3.9.1 flag');
ok(C('magmortar').blueprint_compat === true, 'Magmortar (pokejokers_16, batch 7) takes its 3.9.1 flag');
ok(C('wartortle').perishable_compat === false && C('zubat').perishable_compat === false && C('mareep').perishable_compat === false && C('treecko').perishable_compat === true, 'perishable_compat: Wartortle / Zubat / Mareep off, Treecko on');
ok(C('mega_gengar').eternal_compat === true, 'eternal_compat: Mega Gengar on');
ok(['xmult', 'volatile', 'round_evo', 'lightning_type', 'stage_basic', 'pokemon'].every((x) => C('voltorb').attributes.includes(x)) && C('bulbasaur').attributes.includes('starter'), 'the 3.9.1 attributes (+ the type / stage / pokemon ones of load_pokemon)', C('voltorb').attributes);

// ---------------------------------------------------------------- enhancement gates
const GATES = { vaporeon: 'm_bonus', jolteon: 'm_gold', flareon: 'm_mult', leafeon: 'm_lucky', glaceon: 'm_glass', probopass: 'm_stone', gholdengo: 'm_gold' };
for (const [n, g] of Object.entries(GATES)) ok(C(n).enhancement_gate === g, `enhancement gate: ${n} needs ${g}`, C(n).enhancement_gate);
{
  start('PK391GATE');
  const pp = C('probopass');
  for (const c of G.playing_cards) if (c.config.center.key === 'm_stone') c.set_ability(P_CENTERS.c_base);
  ok(pp.in_pool(pp) === false, 'gate: no Stone card in the deck -> Probopass never spawns');
  G.playing_cards[0].set_ability(P_CENTERS.m_stone);
  ok(pp.in_pool(pp) === true, 'gate: a Stone card in the deck -> it can');
}

// ---------------------------------------------------------------- config numbers (read by the ported logic in play)
ok(C('voltorb').config.extra.Xmult === 1.75 && C('electrode').config.extra.Xmult === 2.25, 'config: Voltorb X1.75, Electrode X2.25');
{
  start('PK391VOLT');
  const v = add('j_poke_voltorb');
  const r = play(hand(['S_A']));
  ok(r.total.mult === 1.75 && v.debuff, 'Voltorb fires X1.75 (3.9.1) then faints', r.total);
}
{
  start('PK391ELEC');
  add('j_poke_electrode');
  const d0 = G.GAME.dollars;
  const r = play(hand(['S_A']));
  ok(r.total.mult === 2.25 && G.GAME.dollars === d0 + 3, 'Electrode fires X2.25 (3.9.1) and $3', { t: r.total, d: G.GAME.dollars - d0 });
}
ok(C('larvitar').config.extra.chip_mod === 10 && C('pupitar').config.extra.chip_mod === 15, 'config: Larvitar +10 / Pupitar +15 Chips per Full House card');
{
  start('PK391LARV');
  add('j_poke_larvitar');
  const cards = hand(['S_K', 'H_K', 'D_K', 'S_2', 'H_2']);
  play(cards);
  ok(cards.every((c) => c.ability.perma_bonus === 10), 'Larvitar: every Full House card permanently +10 Chips', cards.map((c) => c.ability.perma_bonus));
}
ok(C('grubbin').config.extra.rounds === 4 && C('charjabug').config.extra.mult === 7, 'config: Grubbin 4 rounds, Charjabug +7');
{
  start('PK391CHAR');
  add('j_poke_charjabug');
  const r = play(hand(['S_A']));
  ok(r.total.mult === 1 + 7, 'Charjabug: +7 Mult for itself (the one Lightning joker)', r.total);
}
ok(C('kricketot').config.extra.money === 4 && C('kricketune').config.extra.money === 4, 'config: Kricketot $4; Kricketune $4 (both reworked in batch 7)');
{
  start('PK391KRIC');
  add('j_poke_kricketot');
  const d0 = G.GAME.dollars;
  play(hand(['S_2', 'H_3', 'D_4', 'C_5']));
  G.E_MANAGER.flush();
  ok(G.GAME.dollars === d0 + 4, 'Kricketot: $4 for a 4-suit 4-card hand', G.GAME.dollars - d0);
}
ok(C('primeape').config.evo_rqmt === 29 && C('ursaring').config.extra.mult_mod === 2, 'config: Primeape evolves after 29 primes, Ursaring +2 per skipped pack');
// skipped (reworks): the 3.2.1 numbers stay
// (Glaceon and Jirachi Power are reworked since batch 7: their 3.9.1 numbers are pokermon_391_reworks_b_test.mjs's)
// (Vikavolt, Ursaluna and Annihilape are reworked since batch 8: their 3.9.1 numbers are pokermon_391_reworks_c_test.mjs's)
// (batch 10: the Hazard layer jokers left the holds; their whole 3.9.1 configs are taken — pokermon_391_hazard_test.mjs)
ok(C('mega_steelix').config.extra.stone_held === 4 && C('qwilfish').config.extra.chip_mod === 15
  && C('roggenrola').config.extra.mult_mod === 5 && C('golurk').config.extra.Xmult_multi === 1.3 && C('tarountula').config.extra.rounds === 4,
'the former Hazard holds take their 3.9.1 numbers (batch 10)');
ok(C('spidops').config.extra.card_goal === 8 && C('spidops').config.extra.h_max === undefined, 'Spidops: its 3.9.1 config replaces the 3.2.1 one', C('spidops').config.extra);

// ---------------------------------------------------------------- house rules / kept fixes
ok(/contains/.test(DATA.loc.descriptions.Joker.j_poke_deino.text[1]) && /contains/.test(DATA.loc.descriptions.Joker.j_poke_zweilous.text[1]), 'house rule: Deino / Zweilous "contains a Three of a Kind"');
ok(P_CENTERS.b_poke_revenantdeck && !P_CENTERS.b_poke_revenanteck, 'kept fix: the Revenant deck typo');

// ---------------------------------------------------------------- the renamed boss
{
  const hb = P_BLINDS.bl_poke_iridescent_hacker;
  ok(hb && !P_BLINDS.bl_poke_cgoose, 'the boss is registered as bl_poke_iridescent_hacker (bl_poke_cgoose is not)');
  ok(hb && hb.boss.showdown && hb.mult === 2 && hb.dollars === 8 && hb.boss_colour === '#505860' && hb.atlas === 'poke_AtlasBossblinds391' && hb.pos.y === 25, 'Iridescent Hacker: showdown, x2, $8, 3.9.1 colour + art', hb && [hb.boss_colour, hb.atlas, hb.pos]);
  ok(DATA.loc.descriptions.Blind.bl_poke_iridescent_hacker && DATA.loc.descriptions.Blind.bl_poke_iridescent_hacker.name === 'Iridescent Hacker', 'its 3.9.1 name');
  ok(AL.isRenamed('bl_poke_cgoose') && AL.resolveKey('bl_poke_cgoose', (k) => !!P_BLINDS[k]) === 'bl_poke_iridescent_hacker', 'the old key resolves to the new one (aliases.js, now active)');
  ok(AL.aliasesOf('bl_poke_iridescent_hacker').includes('bl_poke_cgoose'), '... and its stored stickers / records count for the new key');
  start('PK391HACK', {}, { noBlind: true });
  G.FORCE_BOSS = undefined;
  G.GAME.round_resets.ante = 8;
  for (const k of Object.keys(G.GAME.bosses_used)) G.GAME.bosses_used[k] = k === 'bl_poke_iridescent_hacker' ? 0 : 99;
  ok(get_new_boss() === 'bl_poke_iridescent_hacker', 'eligible at ante 8');
  G.GAME.round_resets.ante = 1;
  G.FORCE_BOSS = 'bl_poke_iridescent_hacker';
  G.GAME.round_resets.blind_choices.Boss = 'bl_poke_iridescent_hacker';
  const ch = add('j_poke_charmander'), sq = add('j_poke_squirtle');
  act({ type: 'select_blind' }); clearHand(); nextRound(); clearHand(); nextRound();
  // (batch 17: 3.9.1's own Hacker logic — the types live in blind.effect.ptypes, picked at setting_blind / press_play)
  ok(G.GAME.blind.config.blind.key === 'bl_poke_iridescent_hacker' && Array.isArray(G.GAME.blind.effect && G.GAME.blind.effect.ptypes), 'the fight: types picked at set_blind (3.9.1 logic since batch 17)');
  const want = (c) => G.GAME.blind.effect.ptypes.includes(c.ability.extra.ptype);
  play(hand(['S_2']));
  ok([ch, sq].every((c) => !!c.debuff === want(c)), 'after a hand: jokers of its types are debuffed');
  winRound();
}

// ---------------------------------------------------------------- art: the 3.9.1 sheets
// (ART, crops: poke_art_helpers.mjs)
const meanDiff = (a, b) => { let s = 0; for (let i = 0; i < a.length; i++) s += Math.abs(a[i] - b[i]); return s / a.length; };

if (!ART) console.log('(Pokermon art not on disk: the 3.9.1 crop checks are skipped)');
else {
  // The 3.2.1 cell of each card (data.js PokemonSprites / its own pos) vs its 3.9.1 cell, both from disk.
  const SPR321 = DATA.globals.PokemonSprites;
  const oldCell = (c) => {
    if (c.set === 'Joker') {
      const n = c.key.replace(/^j_poke_/, '');
      const info = SPR321[n];
      if (info && info.base && info.base.pos) {
        const pos = Array.isArray(info.base.pos) ? info.base.pos[0] : info.base.pos;
        const gen = C(n).gen;
        const atlas = info.gen_atlas && gen ? 'AtlasJokersBasicGen' + String(gen).padStart(2, '0') : info.others_atlas ? 'AtlasJokersBasicOthers' : 'AtlasJokersBasicNatdex';
        return { atlas: 'poke_' + atlas, pos };
      }
    }
    if (c.key === 'bl_poke_iridescent_hacker') return { atlas: 'poke_AtlasBossblinds', pos: { x: 0, y: 0 } }; // (Chartreuse Chamber's cell)
    return { atlas: c.atlas.replace(/391$/, ''), pos: c.pos };
  };
  const C2 = MODS.pokermon.content;
  // (content 3.9.1 adds — batch 10: Miracle Seed, Heavy-Duty Boots, the Seed card — has no 3.2.1 cell to compare)
  // (and the jokers 3.9.1 adds, new-jokers stack: data391.js new_jokers — pokermon_391_new_<sub>_test.mjs checks their art; and
  // the Meteorite, sub-batch 14, whose 3.2.1 cell is empty: pokermon_391_new_14_test.mjs checks it; the Mega Berry Juice, batch 16:
  // pokermon_391_megas_test.mjs)
  // (batch 17: the five new boss blinds and the Ludicolo card; pokermon_391_batch17_test.mjs checks their art)
  const NEW_391 = new Set(['c_poke_miracleseed', 'c_poke_heavyboots', 'm_poke_seed', 'c_poke_meteorite', 'c_poke_berry_juice_mega',
    'bl_poke_mirror', 'bl_poke_rocket', 'bl_poke_star', 'bl_poke_gray_godfather', 'bl_poke_white_executive', 'm_poke_ludicolo',
    ...Object.keys(D391.new_jokers || {}).map((n) => 'j_poke_' + n),
    // (the owner's designs: new to the port, no 3.2.1 joker to compare; pokermon_new_jokers_test.mjs checks their 3.9.1 cells)
    ...(P.PORTED_FILES['micatro/pokejokers_designs'] || []).map((n) => 'j_poke_' + n)]);
  const cards = [...C2.centers, ...C2.blinds, ...C2.stickers, ...MODS.pokermon.sleeves].filter((c) => !NEW_391.has(c.key) && (/391$/.test(c.atlas || '') && c.pos && !/AtlasJokersBasicOthers391|AtlasDecksBasic391/.test(c.atlas) || ['j_poke_rival', 'b_poke_pokemondeck'].includes(c.key)));
  const fileOf = (a) => decodeURIComponent(ATLASES[a].src).replace(/^.*\/assets\/2x\//, '');
  const cell = (a, pos) => { const A = ATLASES[a], cw = (A.px || 71) * 2, chh = (A.py || 95) * 2; return [pos.x * cw, pos.y * chh, cw, chh]; };
  const want = {}; // file -> rects
  const req = (file, id, rect) => ((want[file] || (want[file] = {}))[id] = rect);
  for (const c of cards) {
    const o = oldCell(c);
    if (!ATLASES[o.atlas]) { ok(false, 'old atlas registered: ' + o.atlas); continue; }
    req(fileOf(o.atlas), c.key + '|old', cell(o.atlas, o.pos));
    req(fileOf(c.atlas), c.key + '|new', cell(c.atlas, c.pos));
  }
  const px = {};
  for (const [file, rects] of Object.entries(want)) Object.assign(px, await crops(path.join(ART, file), rects));
  // 3.9.1 redrew these on purpose: Flower's card (the Seed / Flower rework art), the renamed boss's chip (a new boss), and
  // Unown's card (the Unown rework, batch 10b: another frame and badge; its letters, the soul cells, are unchanged).
  const REDRAWN = new Set(['m_poke_flower', 'bl_poke_iridescent_hacker', 'j_poke_unown']);
  const same = [], touched = [], differ = [], outside = [];
  for (const c of cards) {
    const a = px[c.key + '|old'], b = px[c.key + '|new'];
    if (!a || !b) continue;
    if (!a.inside || !b.inside) { outside.push(c.key); continue; }
    const d = meanDiff(a.px, b.px);
    if (d === 0) same.push(c.key); else if (d <= 3) touched.push(`${c.key} ${d.toFixed(2)}`); else differ.push(`${c.key} ${d.toFixed(1)}`);
  }
  const unexpected = differ.filter((s) => !REDRAWN.has(s.split(' ')[0]));
  console.log(`art: ${cards.length} Pokermon cards on 3.9.1 sheets — ${same.length} identical, ${touched.length} touched up, redrawn: ${differ.join(', ') || 'none'}`);
  ok(cards.length > 500, `Pokermon cards on 3.9.1 sheets checked (${cards.length})`);
  ok(outside.length === 0, 'every 3.9.1 cell lies inside its sheet', outside);
  ok(unexpected.length === 0, `every card shows the same picture at its 3.9.1 cell (${same.length} identical, ${touched.length} touched up)`, unexpected);
  ok(differ.length === REDRAWN.size, 'the redrawn ones are the listed ones', differ);
  // The moved jokers (3.9.1 re-laid the Natdex legendaries / forms into the Gen sheets): their new cells, by name.
  for (const n of ['aegislash', 'arceus', 'vivillon', 'flabebe', 'pumpkaboo', 'gourgeist', 'zygarde']) {
    const c = C(n);
    if (!c || NEW_391.has(c.key)) continue; // (Aegislash is one of the owner's designs: no 3.2.1 joker)
    ok(same.includes(c.key) || touched.some((s) => s.startsWith(c.key + ' ')), `moved by 3.9.1: ${n} (${c.atlas} ${c.pos.x},${c.pos.y}) shows its 3.2.1 picture`);
  }
  // Unown is on its 3.9.1 card since batch 10b (the Unown rework); the add-ons keep the 3.2.1 sheets.
  ok(C('unown').atlas === 'poke_AtlasJokersBasicGen02391', 'Unown: its 3.9.1 card (batch 10b)', C('unown').atlas);
  ok(C('rotomdex').atlas === 'poke_AtlasJokersBasicOthers391' && P_CENTERS.b_poke_stadiumdeck.atlas === 'poke_AtlasDecksBasic391' && P_CENTERS.c_poke_fake_banker.atlas === 'poke_AtlasJokersSeriesAGen03', 'the batch-1 placeholder art is kept (Rotom Dex, decks, Jirachi wishes)');
}

done();
